const elements = Object.fromEntries(
  [...document.querySelectorAll('[id]')].map((element) => [element.id.replaceAll('-', '_'), element]),
);
const appShell = document.querySelector('.app-shell');

const state = {
  mode: 'switzerland',
  point: null,
  polygon: [],
  radiusKm: 10,
  durationMinutes: 180,
  routePreference: 'either',
  closures: [],
  closureCheckedAt: null,
  jobId: 0,
  lastRoute: null,
  lastGeoJson: null,
  lastProfile: null,
  selectedProfilePoint: null,
  configured: false,
};

function toast(message, timeout = 4200) {
  elements.toast.textContent = message;
  elements.toast.hidden = false;
  clearTimeout(toast.timer);
  toast.timer = setTimeout(() => (elements.toast.hidden = true), timeout);
}

let swissMap;
try {
  swissMap = new SwissMap(elements.map_stage, {
    onError: (message) => toast(message),
  });
} catch (error) {
  elements.error_box.hidden = false;
  elements.error_box.textContent = `Die Karte konnte nicht gestartet werden: ${error.message}`;
}

const worker = new Worker(new URL('./router.worker.js', import.meta.url), { type: 'module' });

function updateRange(input) {
  const progress = ((Number(input.value) - Number(input.min)) / (Number(input.max) - Number(input.min))) * 100;
  input.style.setProperty('--range-progress', `${progress}%`);
}

updateRange(elements.duration);
updateRange(elements.radius);

function formatStatDuration(minutes) {
  const rounded = Math.max(0, Math.round(minutes));
  const hours = Math.floor(rounded / 60);
  const rest = rounded % 60;
  return rest ? `${hours}h ${rest}m` : `${hours}h`;
}

function updateSelectionUi() {
  document.querySelectorAll('[data-mode]').forEach((button) => {
    button.setAttribute('aria-pressed', String(button.dataset.mode === state.mode));
  });
  elements.radius_controls.hidden = state.mode !== 'point';
  elements.draw_actions.hidden = state.mode !== 'polygon';
  swissMap?.clearSelection();
  if (state.mode === 'switzerland') {
    elements.selection_hint.hidden = true;
    elements.selection_hint.textContent = '';
  } else if (state.mode === 'point') {
    elements.selection_hint.hidden = false;
    elements.selection_hint.innerHTML = state.point
      ? '<span aria-hidden="true">✓</span><span>Kartenpunkt gesetzt. Der Start wird innerhalb des Kreises gewählt.</span>'
      : '<span aria-hidden="true">◎</span><span><strong>Auf die Karte klicken</strong>, um den Mittelpunkt zu setzen.</span>';
    if (state.point) swissMap?.showPointSelection(state.point, state.radiusKm);
  } else {
    const polygonReady = state.polygon.length >= 3;
    elements.selection_hint.hidden = false;
    elements.selection_hint.innerHTML = polygonReady
      ? '<span aria-hidden="true">✓</span><span>Nur die Start-Haltestelle muss im Gebiet liegen.</span>'
      : '<span aria-hidden="true">◎</span><span>Mindestens drei Punkte <strong>auf der Karte anklicken</strong>.</span>';
    swissMap?.showPolygonSelection(state.polygon, polygonReady);
  }
}

document.querySelectorAll('[data-mode]').forEach((button) => {
  button.addEventListener('click', () => {
    state.mode = button.dataset.mode;
    if (state.mode === 'polygon') {
      state.polygon = [];
      swissMap?.focusSwitzerland();
    }
    updateSelectionUi();
  });
});

elements.radius.addEventListener('input', () => {
  state.radiusKm = Number(elements.radius.value);
  elements.radius_value.textContent = `${state.radiusKm} km`;
  updateRange(elements.radius);
  updateSelectionUi();
});

elements.duration.addEventListener('input', () => {
  state.durationMinutes = Number(elements.duration.value);
  elements.duration_value.textContent = formatDuration(state.durationMinutes);
  updateRange(elements.duration);
});

const routePreferenceButtons = [...document.querySelectorAll('[data-route-preference]')];
routePreferenceButtons.forEach((button) => {
  button.addEventListener('click', () => {
    const isActive = button.getAttribute('aria-pressed') === 'true';
    const activeCount = routePreferenceButtons.filter(
      (option) => option.getAttribute('aria-pressed') === 'true',
    ).length;
    if (isActive && activeCount === 1) {
      toast('Mindestens ein Routentyp muss aktiviert bleiben.');
      return;
    }
    button.setAttribute('aria-pressed', String(!isActive));
    const activeTypes = routePreferenceButtons
      .filter((option) => option.getAttribute('aria-pressed') === 'true')
      .map((option) => option.dataset.routePreference);
    state.routePreference = activeTypes.length === 2 ? 'either' : activeTypes[0];
  });
});

elements.clear_selection.addEventListener('click', () => {
  state.point = null;
  state.polygon = [];
  updateSelectionUi();
});

let pointerStart = null;
elements.map_stage.addEventListener('pointerdown', (event) => {
  pointerStart = [event.clientX, event.clientY];
});
elements.map_stage.addEventListener('pointerup', (event) => {
  if (!pointerStart) return;
  const movement = Math.hypot(event.clientX - pointerStart[0], event.clientY - pointerStart[1]);
  pointerStart = null;
  if (movement > 6) return;
  const routePosition = swissMap?.pickRoutePosition(event.clientX, event.clientY);
  if (routePosition && state.lastProfile?.points?.length) {
    selectProfileFraction(routePosition.fraction);
    return;
  }
  if (state.mode === 'switzerland') return;
  const coordinate = swissMap?.pickCoordinate(event.clientX, event.clientY);
  if (!coordinate || !isInsideSwissBounds(coordinate)) {
    toast('Bitte innerhalb der Schweiz klicken.');
    return;
  }
  if (state.mode === 'point') state.point = coordinate;
  if (state.mode === 'polygon') state.polygon.push(coordinate);
  updateSelectionUi();
});

elements.layers_button.addEventListener('click', () => {
  const open = elements.layer_menu.hidden;
  elements.layer_menu.hidden = !open;
  elements.layers_button.setAttribute('aria-expanded', String(open));
});
elements.map_zoom_in.addEventListener('click', () => swissMap?.zoomStep(1));
elements.map_zoom_out.addEventListener('click', () => swissMap?.zoomStep(-1));
elements.hiking_layer.addEventListener('change', () => swissMap?.setOverlay('hiking', elements.hiking_layer.checked));
elements.stops_layer.addEventListener('change', () => swissMap?.setOverlay('stops', elements.stops_layer.checked));
function setBusy(busy, message = '') {
  elements.generate.disabled = busy;
  elements.mobile_new_route.disabled = busy;
  elements.generate_label.textContent = busy ? message || 'Route wird gesucht …' : 'Zufallswanderung erstellen';
  elements.mobile_new_route_label.textContent = busy
    ? message || 'Route wird gesucht …'
    : 'Neue Zufallswanderung erstellen';
  if (!busy) elements.progress_bar.style.width = '0%';
}

function showError(message, suggestion = '') {
  elements.error_box.hidden = false;
  elements.error_box.textContent = suggestion ? `${message} ${suggestion}` : message;
}

function requestArea() {
  if (state.mode === 'switzerland') return { type: 'switzerland' };
  if (state.mode === 'point') {
    if (!state.point) throw new Error('Bitte zuerst einen Punkt auf der Karte setzen.');
    return { type: 'point', coordinate: state.point, radiusKm: state.radiusKm };
  }
  if (state.polygon.length < 3) {
    throw new Error('Bitte mindestens drei Punkte für das Gebiet setzen.');
  }
  return { type: 'polygon', coordinates: state.polygon };
}

async function generateRoute(event) {
  event?.preventDefault();
  elements.error_box.hidden = true;
  try {
    const area = requestArea();
    state.jobId += 1;
    setBusy(true);
    elements.status_line.hidden = false;
    elements.status_dot.classList.add('warning');
    elements.status_text.textContent = 'Routingdaten werden vorbereitet …';
    worker.postMessage({
      type: 'generate',
      jobId: state.jobId,
      request: {
        area,
        durationMinutes: state.durationMinutes,
        routeType: state.routePreference,
        allowMountainTrails: true,
        seed: `${Date.now()}-${crypto.getRandomValues(new Uint32Array(1))[0]}`,
        closures: state.closures,
      },
    });
  } catch (error) {
    setBusy(false);
    showError(error.message);
  }
}

elements.planner_form.addEventListener('submit', generateRoute);
elements.mobile_new_route.addEventListener('click', generateRoute);
elements.download_gpx.addEventListener('click', () => {
  if (state.lastRoute && state.lastGeoJson) downloadGpx(state.lastRoute, state.lastGeoJson);
});

const MOBILE_SHEET_COMPACT = 1 / 3;
const MOBILE_SHEET_EXPANDED = 1;
let sheetDrag = null;

function setMobileSheetExpanded(expanded, { resetScroll = false } = {}) {
  elements.planner_panel.classList.toggle('is-expanded', expanded);
  elements.sheet_handle.setAttribute('aria-expanded', String(expanded));
  if (resetScroll) elements.panel_scroll.scrollTop = 0;
  if (!sheetDrag) {
    elements.planner_panel.style.removeProperty('height');
    elements.planner_panel.style.removeProperty('max-height');
  }
}

function mobileSheetHeights() {
  const viewportHeight = window.visualViewport?.height || window.innerHeight;
  return {
    compact: viewportHeight * MOBILE_SHEET_COMPACT,
    expanded: viewportHeight * MOBILE_SHEET_EXPANDED,
  };
}

elements.panel_scroll.addEventListener('scroll', () => {
  if (sheetDrag || window.innerWidth > 760 || !elements.planner_panel.classList.contains('has-result')) return;
  if (elements.panel_scroll.scrollTop > 6) setMobileSheetExpanded(true);
}, { passive: true });

elements.sheet_handle.addEventListener('pointerdown', (event) => {
  if (window.innerWidth > 760 || !elements.planner_panel.classList.contains('has-result')) return;
  if (event.pointerType === 'mouse' && event.button !== 0) return;
  const startHeight = elements.planner_panel.getBoundingClientRect().height;
  sheetDrag = {
    pointerId: event.pointerId,
    startY: event.clientY,
    lastY: event.clientY,
    startHeight,
    wasExpanded: elements.planner_panel.classList.contains('is-expanded'),
  };
  elements.sheet_handle.setPointerCapture(event.pointerId);
  elements.planner_panel.classList.add('is-dragging');
  elements.planner_panel.style.height = `${startHeight}px`;
  elements.planner_panel.style.maxHeight = `${startHeight}px`;
  event.preventDefault();
});

elements.sheet_handle.addEventListener('pointermove', (event) => {
  if (event.pointerId !== sheetDrag?.pointerId) return;
  const { compact, expanded } = mobileSheetHeights();
  sheetDrag.lastY = event.clientY;
  const height = Math.max(
    compact,
    Math.min(expanded, sheetDrag.startHeight + sheetDrag.startY - event.clientY),
  );
  elements.planner_panel.style.height = `${height}px`;
  elements.planner_panel.style.maxHeight = `${height}px`;
  event.preventDefault();
});

function finishSheetDrag(event, cancelled = false) {
  if (event.pointerId !== sheetDrag?.pointerId) return;
  const drag = sheetDrag;
  const displacement = drag.startY - drag.lastY;
  let expanded = drag.wasExpanded;
  if (!cancelled && displacement > 34) expanded = true;
  if (!cancelled && displacement < -34) expanded = false;
  sheetDrag = null;
  if (!expanded) elements.panel_scroll.scrollTop = 0;
  elements.planner_panel.classList.toggle('is-expanded', expanded);
  elements.sheet_handle.setAttribute('aria-expanded', String(expanded));
  elements.planner_panel.classList.remove('is-dragging');
  requestAnimationFrame(() => {
    elements.planner_panel.style.removeProperty('height');
    elements.planner_panel.style.removeProperty('max-height');
  });
}

elements.sheet_handle.addEventListener('pointerup', (event) => finishSheetDrag(event));
elements.sheet_handle.addEventListener('pointercancel', (event) => finishSheetDrag(event, true));
elements.sheet_handle.addEventListener('keydown', (event) => {
  if (event.key === 'ArrowUp') setMobileSheetExpanded(true);
  else if (event.key === 'ArrowDown') setMobileSheetExpanded(false, { resetScroll: true });
  else if (event.key === 'Enter' || event.key === ' ') {
    event.preventDefault();
    setMobileSheetExpanded(!elements.planner_panel.classList.contains('is-expanded'));
  } else return;
  event.preventDefault();
});

function profileStats(points) {
  let ascent = 0;
  let descent = 0;
  for (let index = 1; index < points.length; index += 1) {
    const delta = points[index].elevation - points[index - 1].elevation;
    if (delta > 0.5) ascent += delta;
    if (delta < -0.5) descent -= delta;
  }
  return { ascent, descent, distance: points.at(-1)?.distance || 0 };
}

function drawProfile(points, selectedPoint = null) {
  const canvas = elements.profile_chart;
  const rect = canvas.getBoundingClientRect();
  const ratio = Math.min(2, window.devicePixelRatio || 1);
  canvas.width = Math.max(1, Math.floor(rect.width * ratio));
  canvas.height = Math.max(1, Math.floor(rect.height * ratio));
  const context = canvas.getContext('2d');
  context.scale(ratio, ratio);
  const width = rect.width;
  const height = rect.height;
  context.clearRect(0, 0, width, height);
  if (!points?.length) return;
  const elevations = points.map((point) => point.elevation);
  const min = Math.min(...elevations);
  const max = Math.max(...elevations);
  const distance = Math.max(1, points.at(-1).distance);
  const x = (point) => 8 + (point.distance / distance) * (width - 16);
  const y = (point) => height - 17 - ((point.elevation - min) / Math.max(1, max - min)) * (height - 35);
  const gradient = context.createLinearGradient(0, 0, 0, height);
  gradient.addColorStop(0, 'rgba(243,202,101,.42)');
  gradient.addColorStop(1, 'rgba(243,202,101,0)');
  context.beginPath();
  context.moveTo(x(points[0]), height);
  points.forEach((point) => context.lineTo(x(point), y(point)));
  context.lineTo(x(points.at(-1)), height);
  context.closePath();
  context.fillStyle = gradient;
  context.fill();
  context.beginPath();
  points.forEach((point, index) => (index ? context.lineTo(x(point), y(point)) : context.moveTo(x(point), y(point))));
  context.strokeStyle = '#f3ca65';
  context.lineWidth = 2;
  context.stroke();
  context.fillStyle = 'rgba(255,255,255,.65)';
  context.font = '10px DM Sans';
  context.fillText(`${Math.round(max)} m`, 9, 13);
  context.fillText(`${Math.round(min)} m`, 9, height - 6);
  if (selectedPoint) {
    const selectedX = x(selectedPoint);
    const selectedY = y(selectedPoint);
    context.beginPath();
    context.moveTo(selectedX, selectedY);
    context.lineTo(selectedX, height - 8);
    context.strokeStyle = 'rgba(255,255,255,.52)';
    context.lineWidth = 1;
    context.setLineDash([3, 3]);
    context.stroke();
    context.setLineDash([]);
    context.beginPath();
    context.arc(selectedX, selectedY, 5, 0, Math.PI * 2);
    context.fillStyle = '#ffffff';
    context.fill();
    context.beginPath();
    context.arc(selectedX, selectedY, 3, 0, Math.PI * 2);
    context.fillStyle = '#f3ca65';
    context.fill();
  }
}

function updateProfileResult(route, profile) {
  const geoJson = routeGeoJson(route, profile);
  const officialStats = profileStats(profile.points);
  if (officialStats.distance > 0) {
    route.stats.distanceMeters = officialStats.distance;
    route.stats.ascentMeters = officialStats.ascent;
    route.stats.descentMeters = officialStats.descent;
    route.stats.durationMinutes =
      (officialStats.distance / 1000) * 15 +
      (officialStats.ascent / 100) * 15 +
      (officialStats.descent / 200) * 15;
  }
  if (state.selectedProfilePoint && profile.points.length) {
    const previousTotal = Math.max(1, state.lastProfile?.points?.at(-1)?.distance || 1);
    const fraction = state.selectedProfilePoint.distance / previousTotal;
    const targetDistance = fraction * Math.max(1, profile.points.at(-1).distance);
    state.selectedProfilePoint = profile.points.reduce((nearest, point) =>
      Math.abs(point.distance - targetDistance) < Math.abs(nearest.distance - targetDistance)
        ? point
        : nearest,
    );
    swissMap?.showProfilePoint(state.selectedProfilePoint.coordinate);
  }
  state.lastRoute = route;
  state.lastGeoJson = geoJson;
  state.lastProfile = profile;
  elements.stat_duration.textContent = formatStatDuration(route.stats.durationMinutes);
  elements.stat_distance.textContent = formatDistance(route.stats.distanceMeters);
  elements.stat_ascent.textContent = `↑ ${Math.round(route.stats.ascentMeters)} m`;
  elements.stat_descent.textContent = `↓ ${Math.round(route.stats.descentMeters)} m`;
  drawProfile(profile.points, state.selectedProfilePoint);
}

function selectProfileFraction(fraction) {
  const points = state.lastProfile?.points;
  if (!points?.length) return;
  const clampedFraction = Math.max(0, Math.min(1, fraction));
  const targetDistance = clampedFraction * Math.max(1, points.at(-1).distance);
  state.selectedProfilePoint = points.reduce((nearest, point) =>
    Math.abs(point.distance - targetDistance) < Math.abs(nearest.distance - targetDistance)
      ? point
      : nearest,
  );
  drawProfile(points, state.selectedProfilePoint);
  swissMap?.showProfilePoint(state.selectedProfilePoint.coordinate);
}

function selectProfilePoint(clientX) {
  const rect = elements.profile_chart.getBoundingClientRect();
  const fraction = (clientX - rect.left - 8) / Math.max(1, rect.width - 16);
  selectProfileFraction(fraction);
}

let profilePointerId = null;

elements.profile_chart.addEventListener('pointerdown', (event) => {
  if (event.pointerType === 'mouse' && event.button !== 0) return;
  profilePointerId = event.pointerId;
  elements.profile_chart.setPointerCapture(event.pointerId);
  selectProfilePoint(event.clientX);
});

elements.profile_chart.addEventListener('pointermove', (event) => {
  if (event.pointerId !== profilePointerId) return;
  selectProfilePoint(event.clientX);
});

function stopProfileScrubbing(event) {
  if (event.pointerId !== profilePointerId) return;
  if (elements.profile_chart.hasPointerCapture(event.pointerId)) {
    elements.profile_chart.releasePointerCapture(event.pointerId);
  }
  profilePointerId = null;
}

elements.profile_chart.addEventListener('pointerup', stopProfileScrubbing);
elements.profile_chart.addEventListener('pointercancel', stopProfileScrubbing);
elements.profile_chart.addEventListener('keydown', (event) => {
  if (event.key !== 'Enter' && event.key !== ' ') return;
  event.preventDefault();
  const rect = elements.profile_chart.getBoundingClientRect();
  selectProfilePoint(rect.left + rect.width / 2);
});

async function presentRoute(route, jobId) {
  // The graph already contains a complete elevation profile. Show the route
  // immediately and refine statistics/GPX with the live API in the background.
  const graphProfile = routeGraphProfile(route);
  const graphGeoJson = routeGeoJson(route, graphProfile);
  state.selectedProfilePoint = null;
  const isLoop = route.routeType === 'loop';
  elements.route_type.textContent = isLoop ? 'Rundwanderung' : 'Streckentour';
  elements.route_class.textContent = route.stats.highestClass ? 'Bergwanderweg' : 'Wanderweg';
  elements.route_title.textContent = isLoop
    ? `Rund um ${route.startStop.name}`
    : `${route.startStop.name} → ${route.endStop.name}`;
  elements.route_endpoint.textContent = isLoop
    ? `Start und Ziel: ${route.startStop.name}`
    : `Von ${route.startStop.transport} zu ${route.endStop.transport}`;
  elements.result_card.hidden = false;
  setMobileSheetExpanded(false, { resetScroll: true });
  elements.planner_panel.classList.add('has-result');
  appShell.classList.add('has-route-result');
  swissMap?.resize();
  swissMap?.showRoute(graphGeoJson, route.startStop, route.endStop);
  elements.panel_scroll.scrollTop = 0;
  updateProfileResult(route, graphProfile);
  elements.status_dot.classList.remove('warning');
  elements.status_line.hidden = true;
  setBusy(false);

  const profile = await loadElevationProfile(route);
  if (jobId !== state.jobId) return;
  updateProfileResult(route, profile);
}

worker.addEventListener('message', async (event) => {
  const message = event.data;
  if (message.type === 'configured') {
    state.configured = true;
    elements.status_line.hidden = true;
    elements.status_text.textContent = '';
    elements.demo_box.hidden = message.mode !== 'demo';
    if (message.mode === 'demo') swissMap?.focusCoordinate([7.45, 46.95], 105_000);
    return;
  }
  if (message.jobId !== state.jobId) return;
  if (message.type === 'progress') {
    elements.status_text.textContent = message.message;
    elements.generate_label.textContent = message.message.replace(' …', '');
    elements.mobile_new_route_label.textContent = message.message.replace(' …', '');
    elements.progress_bar.style.width = `${Math.round((message.value || 0) * 100)}%`;
  }
  if (message.type === 'result') void presentRoute(message.route, message.jobId);
  if (message.type === 'error') {
    setBusy(false);
    elements.status_line.hidden = true;
    elements.status_dot.classList.add('warning');
    elements.status_text.textContent = 'Keine passende Route gefunden.';
    showError(message.message, message.suggestion);
  }
});

const manifestUrl = new URL('./data/manifest.json', window.location.href).href;
worker.postMessage({ type: 'configure', jobId: 0, manifestUrl });

loadClosures()
  .then((value) => {
    state.closures = value.closures;
    state.closureCheckedAt = value.timestamp;
  })
  .catch((error) => {
    toast(`${error.message} Routen werden mit dem letzten Graphstand berechnet.`);
  });

window.addEventListener('resize', () => {
  if (state.lastProfile) drawProfile(state.lastProfile.points, state.selectedProfilePoint);
});

updateSelectionUi();
