import 'ol/ol.css';
import Feature from 'ol/Feature.js';
import OlMap from 'ol/Map.js';
import Overlay from 'ol/Overlay.js';
import View from 'ol/View.js';
import CircleGeometry from 'ol/geom/Circle.js';
import LineString from 'ol/geom/LineString.js';
import Point from 'ol/geom/Point.js';
import Polygon from 'ol/geom/Polygon.js';
import { defaults as defaultInteractions } from 'ol/interaction/defaults.js';
import TileLayer from 'ol/layer/Tile.js';
import VectorLayer from 'ol/layer/Vector.js';
import { fromLonLat, get as getProjection, toLonLat, transformExtent } from 'ol/proj.js';
import VectorSource from 'ol/source/Vector.js';
import WMTS from 'ol/source/WMTS.js';
import CircleStyle from 'ol/style/Circle.js';
import Fill from 'ol/style/Fill.js';
import Stroke from 'ol/style/Stroke.js';
import Style from 'ol/style/Style.js';
import WMTSTileGrid from 'ol/tilegrid/WMTS.js';
import { buffer as bufferExtent, getTopLeft, getWidth } from 'ol/extent.js';
import { LAYERS, SWISS_BOUNDS, wmtsTemplate } from './constants.js';

const WEB_MERCATOR = getProjection('EPSG:3857');
const WEB_MERCATOR_EXTENT = WEB_MERCATOR.getExtent();
const BASE_RESOLUTION = getWidth(WEB_MERCATOR_EXTENT) / 256;
const TILE_LEVELS = 20;
const TILE_RESOLUTIONS = Array.from(
  { length: TILE_LEVELS },
  (_, level) => BASE_RESOLUTION / 2 ** level,
);
const TILE_MATRIX_IDS = Array.from({ length: TILE_LEVELS }, (_, level) => String(level));
const SWISS_EXTENT = transformExtent(
  [SWISS_BOUNDS.west, SWISS_BOUNDS.south, SWISS_BOUNDS.east, SWISS_BOUNDS.north],
  'EPSG:4326',
  'EPSG:3857',
);
const VIEW_EXTENT = [
  SWISS_EXTENT[0] - 120_000,
  SWISS_EXTENT[1] - 90_000,
  SWISS_EXTENT[2] + 120_000,
  SWISS_EXTENT[3] + 90_000,
];

function projectCoordinate(coordinate) {
  return fromLonLat([coordinate[0], coordinate[1]]);
}

function routeStyles(mobile) {
  return [
    new Style({
      stroke: new Stroke({
        color: 'rgba(255, 255, 255, 1)',
        width: mobile ? 12.5 : 14.5,
        lineCap: 'round',
        lineJoin: 'round',
      }),
      zIndex: 1,
    }),
    new Style({
      stroke: new Stroke({
        color: '#ff482f',
        width: mobile ? 7 : 8.5,
        lineCap: 'round',
        lineJoin: 'round',
      }),
      zIndex: 2,
    }),
  ];
}

function selectionLineStyle(closed) {
  return new Style({
    stroke: new Stroke({
      color: '#155c9c',
      width: closed ? 4 : 3,
      lineDash: closed ? undefined : [8, 6],
    }),
    fill: closed ? new Fill({ color: 'rgba(13, 67, 116, 0.40)' }) : undefined,
  });
}

export class SwissMap {
  constructor(container, { onError = () => {} } = {}) {
    this.container = container;
    this.onError = onError;
    this.mobile = window.innerWidth < 760;
    this.reportedTileError = false;
    this.routeOverlays = [];
    this.profilePointOverlay = null;
    this.selectionOverlays = [];
    this.routeCoordinates = null;
    this.routeFitFrame = null;
    this.routeRefitTimer = null;

    this.baseLayer = this.createWmtsLayer('topo', true, 0, 1);
    this.overlayLayers = new globalThis.Map([
      ['hiking', this.createWmtsLayer('hiking', false, 10, 0.9)],
      ['stops', this.createWmtsLayer('stops', false, 20, 0.95)],
    ]);

    this.routeSource = new VectorSource({ wrapX: false });
    this.routeLayer = new VectorLayer({
      source: this.routeSource,
      style: routeStyles(this.mobile),
      renderBuffer: 80,
      updateWhileAnimating: true,
      updateWhileInteracting: true,
      zIndex: 100,
    });

    this.selectionSource = new VectorSource({ wrapX: false });
    this.selectionLayer = new VectorLayer({
      source: this.selectionSource,
      renderBuffer: 80,
      updateWhileAnimating: true,
      updateWhileInteracting: true,
      zIndex: 90,
    });

    this.view = new View({
      projection: WEB_MERCATOR,
      center: projectCoordinate(this.mobile ? [8.23, 46.25] : [8.23, 46.83]),
      zoom: 8,
      minZoom: this.mobile ? 8 : 7,
      maxZoom: 19,
      extent: VIEW_EXTENT,
      constrainResolution: true,
      smoothExtentConstraint: false,
    });

    this.map = new OlMap({
      target: container,
      layers: [
        this.baseLayer,
        ...this.overlayLayers.values(),
        this.selectionLayer,
        this.routeLayer,
      ],
      view: this.view,
      controls: [],
      interactions: defaultInteractions({
        altShiftDragRotate: false,
        pinchRotate: false,
        onFocusOnly: false,
      }),
      moveTolerance: 6,
      pixelRatio: Math.min(window.devicePixelRatio || 1, this.mobile ? 2.5 : 2),
    });

    const viewport = container.querySelector('.ol-viewport');
    viewport?.setAttribute('aria-label', 'Interaktive Karte der Schweiz');
    viewport?.setAttribute('role', 'application');

    this.resizeObserver = new ResizeObserver(() => this.resize());
    this.resizeObserver.observe(container);
    this.focusInitialView();
  }

  createWmtsLayer(name, visible, zIndex, opacity) {
    const definition = LAYERS[name];
    const source = new WMTS({
      url: wmtsTemplate(definition),
      layer: definition.id,
      matrixSet: '3857',
      format: definition.format,
      projection: WEB_MERCATOR,
      requestEncoding: 'REST',
      style: 'default',
      tileGrid: new WMTSTileGrid({
        origin: getTopLeft(WEB_MERCATOR_EXTENT),
        resolutions: TILE_RESOLUTIONS,
        matrixIds: TILE_MATRIX_IDS,
      }),
      transition: 0,
      wrapX: false,
      crossOrigin: 'anonymous',
      attributions: '© swisstopo',
    });
    source.on('tileloaderror', () => {
      if (this.reportedTileError) return;
      this.reportedTileError = true;
      this.onError('Kartendaten konnten teilweise nicht geladen werden.');
    });
    return new TileLayer({
      source,
      visible,
      opacity,
      zIndex,
      preload: this.mobile ? 1 : 2,
      cacheSize: this.mobile ? 256 : 512,
    });
  }

  setOverlay(name, visible) {
    this.overlayLayers.get(name)?.setVisible(visible);
  }

  focusSwitzerland() {
    this.view.cancelAnimations();
    this.view.setCenter(projectCoordinate(this.mobile ? [8.23, 46.25] : [8.23, 46.83]));
    this.view.setZoom(8);
  }

  focusInitialView() {
    this.focusSwitzerland();
  }

  focusCoordinate(coordinate, altitude = 180_000) {
    const mapHeight = Math.max(300, this.container.clientHeight);
    const resolution = altitude / mapHeight;
    const zoom = Math.max(
      this.view.getMinZoom(),
      Math.min(this.view.getMaxZoom(), Math.log2(BASE_RESOLUTION / resolution)),
    );
    this.view.cancelAnimations();
    this.view.setCenter(projectCoordinate(coordinate));
    this.view.setZoom(Math.round(zoom));
  }

  focusRoute(coordinates) {
    if (!coordinates?.length) return;
    const projected = coordinates.map(projectCoordinate);
    const extent = projected.reduce(
      (result, coordinate) => [
        Math.min(result[0], coordinate[0]),
        Math.min(result[1], coordinate[1]),
        Math.max(result[2], coordinate[0]),
        Math.max(result[3], coordinate[1]),
      ],
      [Infinity, Infinity, -Infinity, -Infinity],
    );
    const routeSpan = Math.max(extent[2] - extent[0], extent[3] - extent[1]);
    const safeExtent = bufferExtent(extent, Math.max(800, routeSpan * 0.1));
    const mobilePanelPadding = Math.round(this.container.clientHeight / 3) + 56;
    const padding = this.mobile ? [56, 48, mobilePanelPadding, 48] : [90, 100, 90, 400];
    this.view.cancelAnimations();
    if (this.routeFitFrame !== null) cancelAnimationFrame(this.routeFitFrame);
    this.routeFitFrame = requestAnimationFrame(() => {
      this.routeFitFrame = null;
      this.map.updateSize();
      const size = this.map.getSize();
      if (!size?.[0] || !size?.[1]) return;
      this.view.fit(safeExtent, {
        size,
        padding,
        maxZoom: 16,
        nearest: false,
        duration: 0,
      });
      this.map.renderSync();

      // Resolution constraints and extent constraints can occasionally pick a
      // scale that is one step too close. Verify every route vertex against the
      // actual post-layout viewport and zoom out until all of it is visible.
      for (let attempt = 0; attempt < 3; attempt += 1) {
        const allVisible = projected.every((coordinate) => {
          const pixel = this.map.getPixelFromCoordinate(coordinate);
          return pixel &&
            pixel[0] >= padding[3] &&
            pixel[0] <= size[0] - padding[1] &&
            pixel[1] >= padding[0] &&
            pixel[1] <= size[1] - padding[2];
        });
        if (allVisible) break;
        const zoom = this.view.getZoom();
        if (!Number.isFinite(zoom) || zoom <= this.view.getMinZoom()) break;
        this.view.setZoom(zoom - 1);
        this.map.renderSync();
      }
      this.positionRouteCaptions(size, padding);
    });
  }

  positionRouteCaptions(size, padding) {
    const visibleMiddle = (padding[3] + size[0] - padding[1]) / 2;
    this.routeOverlays.forEach((overlay) => {
      if (!overlay.get('routeCaption')) return;
      const pixel = this.map.getPixelFromCoordinate(overlay.getPosition());
      const placeOnLeft = pixel && pixel[0] > visibleMiddle;
      overlay.setPositioning(placeOnLeft ? 'center-right' : 'center-left');
      overlay.setOffset([placeOnLeft ? -13 : 13, 0]);
    });
  }

  zoomStep(direction) {
    const zoom = this.view.getZoom();
    if (!Number.isFinite(zoom)) return;
    this.view.cancelAnimations();
    this.view.animate({
      zoom: Math.max(
        this.view.getMinZoom(),
        Math.min(this.view.getMaxZoom(), Math.round(zoom) + direction),
      ),
      duration: 180,
    });
  }

  pickCoordinate(clientX, clientY) {
    const rect = this.container.getBoundingClientRect();
    const projected = this.map.getCoordinateFromPixel([
      clientX - rect.left,
      clientY - rect.top,
    ]);
    return projected ? toLonLat(projected) : null;
  }

  pickRoutePosition(clientX, clientY) {
    if (!this.routeCoordinates?.length) return null;
    const rect = this.container.getBoundingClientRect();
    const pixel = [clientX - rect.left, clientY - rect.top];
    const routeFeature = this.map.forEachFeatureAtPixel(
      pixel,
      (feature, layer) => (layer === this.routeLayer ? feature : null),
      {
        hitTolerance: this.mobile ? 14 : 10,
        layerFilter: (layer) => layer === this.routeLayer,
      },
    );
    if (!routeFeature) return null;

    const target = this.map.getCoordinateFromPixel(pixel);
    const coordinates = routeFeature.getGeometry()?.getCoordinates();
    if (!target || coordinates?.length < 2) return null;

    let totalLength = 0;
    let closestDistanceSquared = Infinity;
    let closestLength = 0;
    for (let index = 1; index < coordinates.length; index += 1) {
      const start = coordinates[index - 1];
      const end = coordinates[index];
      const dx = end[0] - start[0];
      const dy = end[1] - start[1];
      const segmentLengthSquared = dx * dx + dy * dy;
      const segmentLength = Math.sqrt(segmentLengthSquared);
      const projection = segmentLengthSquared
        ? Math.max(0, Math.min(1, ((target[0] - start[0]) * dx + (target[1] - start[1]) * dy) / segmentLengthSquared))
        : 0;
      const closestX = start[0] + projection * dx;
      const closestY = start[1] + projection * dy;
      const distanceSquared = (target[0] - closestX) ** 2 + (target[1] - closestY) ** 2;
      if (distanceSquared < closestDistanceSquared) {
        closestDistanceSquared = distanceSquared;
        closestLength = totalLength + projection * segmentLength;
      }
      totalLength += segmentLength;
    }

    return { fraction: totalLength ? closestLength / totalLength : 0 };
  }

  addRoutePin(coordinate, stopName, type) {
    const projected = projectCoordinate(coordinate);
    const pin = document.createElement('div');
    pin.className = `route-map-pin route-map-pin--${type}`;
    const shape = document.createElement('span');
    shape.className = 'route-map-pin__shape';
    const center = document.createElement('span');
    center.className = 'route-map-pin__center';
    center.textContent = type === 'loop' ? '↺' : type === 'start' ? 'S' : 'Z';
    shape.append(center);
    pin.append(shape);

    const markerOverlay = new Overlay({
      element: pin,
      position: projected,
      positioning: 'center-center',
      insertFirst: false,
      stopEvent: false,
    });
    this.map.addOverlay(markerOverlay);

    const caption = document.createElement('span');
    caption.className = `route-map-pin__caption route-map-pin__caption--${type}`;
    const role = type === 'loop' ? 'Start/Ziel' : type === 'start' ? 'Start' : 'Ziel';
    caption.textContent = `${role} · ${stopName}`;
    const captionOverlay = new Overlay({
      element: caption,
      position: projected,
      positioning: 'center-left',
      offset: [13, 0],
      insertFirst: false,
      stopEvent: false,
    });
    captionOverlay.set('routeCaption', true);
    this.map.addOverlay(captionOverlay);
    this.routeOverlays.push(markerOverlay, captionOverlay);
  }

  showRoute(feature, startStop, endStop) {
    this.clearRoute();
    this.clearSelection();
    const coordinates = feature.geometry.coordinates;
    if (!coordinates.length) return;
    this.routeCoordinates = coordinates.map((coordinate) => [...coordinate]);
    const routeFeature = new Feature({
      geometry: new LineString(coordinates.map(projectCoordinate)),
    });
    this.routeSource.addFeature(routeFeature);

    const isLoop = endStop.id === startStop.id;
    this.addRoutePin(coordinates[0], startStop.name, isLoop ? 'loop' : 'start');
    if (!isLoop) this.addRoutePin(coordinates.at(-1), endStop.name, 'end');
    this.focusRoute(coordinates);
  }

  showProfilePoint(coordinate) {
    if (!coordinate) return;
    const position = projectCoordinate(coordinate);
    if (this.profilePointOverlay) {
      this.profilePointOverlay.setPosition(position);
      return;
    }
    const element = document.createElement('span');
    element.className = 'profile-route-point';
    this.profilePointOverlay = new Overlay({
      element,
      position,
      positioning: 'center-center',
      insertFirst: false,
      stopEvent: false,
    });
    this.map.addOverlay(this.profilePointOverlay);
  }

  clearProfilePoint() {
    if (!this.profilePointOverlay) return;
    this.map.removeOverlay(this.profilePointOverlay);
    this.profilePointOverlay = null;
  }

  clearRoute() {
    if (this.routeFitFrame !== null) cancelAnimationFrame(this.routeFitFrame);
    this.routeFitFrame = null;
    clearTimeout(this.routeRefitTimer);
    this.routeRefitTimer = null;
    this.routeCoordinates = null;
    this.clearProfilePoint();
    this.routeSource.clear();
    this.routeOverlays.forEach((overlay) => this.map.removeOverlay(overlay));
    this.routeOverlays.length = 0;
  }

  pointStyle(index = 0, radiusMode = false) {
    return new Style({
      image: new CircleStyle({
        radius: radiusMode ? 9 : index === 0 ? 10 : 8,
        fill: new Fill({ color: radiusMode ? '#155c9c' : index === 0 ? '#2aaf70' : '#155c9c' }),
        stroke: new Stroke({ color: '#ffffff', width: 3 }),
      }),
      zIndex: 4,
    });
  }

  showPointSelection(coordinate, radiusKm) {
    this.clearSelection();
    const center = projectCoordinate(coordinate);
    const area = new Feature({ geometry: new CircleGeometry(center, radiusKm * 1000) });
    area.setStyle(new Style({
      fill: new Fill({ color: 'rgba(13, 67, 116, 0.40)' }),
      stroke: new Stroke({ color: '#4ba8ef', width: 3, lineDash: [8, 6] }),
      zIndex: 1,
    }));
    const marker = new Feature({ geometry: new Point(center) });
    marker.setStyle(this.pointStyle(0, true));
    this.selectionSource.addFeatures([area, marker]);
  }

  addSelectionPointLabel(coordinate, index) {
    const element = document.createElement('div');
    element.className = `selection-point-label${index === 0 ? ' selection-point-label--start' : ''}`;
    element.textContent = String(index + 1);
    const overlay = new Overlay({
      element,
      position: projectCoordinate(coordinate),
      positioning: 'center-center',
      insertFirst: false,
      stopEvent: false,
    });
    this.map.addOverlay(overlay);
    this.selectionOverlays.push(overlay);
  }

  showPolygonSelection(coordinates, closed = false) {
    this.clearSelection();
    if (!coordinates.length) return;
    const projected = coordinates.map(projectCoordinate);
    if (closed && projected.length >= 3) {
      const ring = [...projected, projected[0]];
      const area = new Feature({ geometry: new Polygon([ring]) });
      area.setStyle(selectionLineStyle(true));
      this.selectionSource.addFeature(area);
    } else if (projected.length >= 2) {
      const line = new Feature({ geometry: new LineString(projected) });
      line.setStyle(selectionLineStyle(false));
      this.selectionSource.addFeature(line);
    }

    coordinates.forEach((coordinate, index) => {
      const marker = new Feature({ geometry: new Point(projected[index]) });
      marker.setStyle(this.pointStyle(index));
      this.selectionSource.addFeature(marker);
      this.addSelectionPointLabel(coordinate, index);
    });
  }

  clearSelection() {
    this.selectionSource.clear();
    this.selectionOverlays.forEach((overlay) => this.map.removeOverlay(overlay));
    this.selectionOverlays.length = 0;
  }

  resize() {
    this.map?.updateSize();
    if (this.routeCoordinates?.length) {
      clearTimeout(this.routeRefitTimer);
      this.routeRefitTimer = setTimeout(() => this.focusRoute(this.routeCoordinates), 60);
    }
  }

  dispose() {
    this.resizeObserver.disconnect();
    this.clearRoute();
    this.clearSelection();
    this.map.setTarget(null);
  }
}
